package octal

import (
	"errors"
)

// ParseOctal converts an octal number, represented as a string, to its
// decimal equivalent using first principles (no built-in conversion).
//
// Invalid input (any character that is not an octal digit 0-7) is treated
// as octal 0 and an error is returned.
func ParseOctal(input string) (int64, error) {
	var value int64
	for _, c := range input {
		if c < '0' || c > '7' {
			return 0, errors.New("invalid octal input")
		}
		value = value*8 + int64(c-'0')
	}
	return value, nil
}

